<article class="fdshop-card" data-product-id="<?php echo(int)$item->id;?>" data-price="<?php echo$e($item->current_price);?>" data-visual-state="<?php echo$e($item->visual_state);?>"><div class="fdshop-card__visual fdshop-product-visual--<?php echo$e($item->visual_state);?>"><div class="fdshop-card__media"><a class="fdshop-card__image-link" href="<?php echo$e($item->detail_url);?>" aria-label="Details zu <?php echo$e($item->product_name);?>"><?php if($item->image_is_placeholder):?><img class="fdshop-card__placeholder" src="<?php echo$e($item->image_url);?>" alt="<?php echo$e($item->product_name);?>" loading="lazy" width="400" height="400"><?php else:?><picture><source media="(max-width:520px)" srcset="<?php echo$e($item->image_mobile_url);?>"><source media="(min-width:521px)" srcset="<?php echo$e($item->image_small_url);?>"><img class="fdshop-card__product-image" src="<?php echo$e($item->image_url);?>" alt="<?php echo$e($item->product_name);?>" loading="lazy" width="400" height="400"></picture><?php endif;?></a><div class="fdshop-card__ribbons" aria-label="Produktkennzeichnungen"><?php if($item->visual_state==='action'):?><span class="fdshop-ribbon fdshop-ribbon--action">% Angebot</span><?php endif;?><?php if((int)$item->ribbon_new===1):?><span class="fdshop-ribbon fdshop-ribbon--new">Neu</span><?php endif;?><?php if((int)$item->ribbon_hot===1):?><span class="fdshop-ribbon fdshop-ribbon--hot">Hot</span><?php endif;?><?php if((int)$item->ribbon_bundle===1):?><span class="fdshop-ribbon fdshop-ribbon--bundle">Bundle</span><?php endif;?><?php if(($item->buyer_group_alias??'')==='permit_holder'):?><span class="fdshop-ribbon fdshop-ribbon--f3">F3</span><?php endif;?><?php if(in_array((string)$item->unit_type,['Display','Schinken','VE'],true)):?><span class="fdshop-ribbon fdshop-ribbon--package"><?php echo$e(strtoupper((string)$item->unit_type));?></span><?php endif;?></div></div><div class="fdshop-card__body"><h2 class="fdshop-card__title"><a href="<?php echo$e($item->detail_url);?>"><?php echo$e($item->product_name);?></a></h2><?php if(trim((string)$item->short_description)!==''):?><p class="fdshop-card__description"><?php echo nl2br($e($item->short_description));?></p><?php endif;?><div class="fdshop-card__actions"><a class="btn btn-primary btn-sm" href="<?php echo$e($item->detail_url);?>">Details</a><?php if($item->media['video']!==null):?><button class="btn btn-dark btn-sm" type="button" data-fdshop-video="<?php echo$e($item->media['video']);?>" data-product-name="<?php echo$e($item->product_name);?>" aria-label="Produktvideo zu <?php echo$e($item->product_name);?> ansehen" title="Produktvideo ansehen"><i class="fa-solid fa-video" aria-hidden="true"></i></button><?php endif;?><p class="fdshop-stock <?php echo$e($item->stock_class);?>"><strong><?php echo$e($item->in_stock);?></strong></p></div></div></div><div class="fdshop-card__info"><dl class="fdshop-card__facts" aria-label="Technische Produktdaten"><?php foreach($item->card_facts as $fact):?><div class="fdshop-card__fact" title="<?php echo$e($fact['label']);?>"><dt class="visually-hidden"><?php echo$e($fact['label']);?></dt><dd aria-label="<?php echo$e($fact['label'].': '.$fact['value']);?>"><img src="<?php echo$e(\Joomla\CMS\Uri\Uri::root(true).'/media/com_fdshop/images/product-facts/'.$fact['icon']);?>" alt="" aria-hidden="true" width="28" height="28" loading="lazy"><span><?php echo$e($fact['value']);?></span></dd></div><?php endforeach;?></dl><div class="fdshop-card__commerce"><div class="fdshop-card__price" data-effective-price="<?php echo$e($item->current_price);?>"><?php if($item->has_discount):?><span class="fdshop-card__regular-price"><?php echo$e($item->regular_price_formatted);?></span><?php endif;?><strong><?php echo$e($item->price_formatted);?></strong><small>inkl. MwSt.</small></div><?php if($purchaseEnabled)echo LayoutHelper::render('purchase.action',PurchaseHelper::data($item,'piece'),JPATH_COMPONENT_SITE.'/layouts');?></div></div></article>
